CREATE TABLE public.knowledge_resources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, title text NOT NULL, summary text NOT NULL DEFAULT '', publisher text NOT NULL, original_url text NOT NULL, category text NOT NULL DEFAULT 'research', region text NOT NULL DEFAULT 'Global', language text NOT NULL DEFAULT 'en', published_at date, verified_at timestamptz, licence_name text NOT NULL DEFAULT 'Unknown — check publisher', licence_url text, reuse_conditions text NOT NULL DEFAULT 'Check the original publisher for reuse rights.', rights_status text NOT NULL DEFAULT 'PENDING_REVIEW' CHECK (rights_status IN ('OWNED_BY_VERFIAI','PUBLIC_DOMAIN','OPEN_LICENSED','PARTNER_LICENSED','LINK_ONLY','RESTRICTED','PENDING_REVIEW','TAKEDOWN_REVIEW','REMOVED')), rights_reviewed_at timestamptz, permission_reference text, hosting_allowed boolean NOT NULL DEFAULT false, redistribution_allowed boolean NOT NULL DEFAULT false, commercial_reuse_allowed boolean NOT NULL DEFAULT false, kind text NOT NULL DEFAULT 'index' CHECK (kind IN ('index','library')), access_level text NOT NULL DEFAULT 'preview' CHECK (access_level IN ('preview','analyst')), preview_content text NOT NULL DEFAULT '', full_content text, file_version text NOT NULL DEFAULT '1', source_count integer NOT NULL DEFAULT 0, evidence_strength text, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (kind <> 'library' OR access_level = 'preview' OR rights_status IN ('OWNED_BY_VERFIAI','PUBLIC_DOMAIN','OPEN_LICENSED','PARTNER_LICENSED')), CHECK (NOT hosting_allowed OR rights_status IN ('OWNED_BY_VERFIAI','PUBLIC_DOMAIN','OPEN_LICENSED','PARTNER_LICENSED')), CHECK (NOT published OR rights_status NOT IN ('PENDING_REVIEW','TAKEDOWN_REVIEW','REMOVED')));
GRANT SELECT ON public.knowledge_resources TO anon, authenticated;
GRANT ALL ON public.knowledge_resources TO service_role;
ALTER TABLE public.knowledge_resources ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published resources metadata" ON public.knowledge_resources FOR SELECT TO anon, authenticated USING (published AND rights_status NOT IN ('PENDING_REVIEW','TAKEDOWN_REVIEW','REMOVED'));
CREATE INDEX knowledge_resources_browse_idx ON public.knowledge_resources(kind, published, category, published_at DESC);
CREATE INDEX knowledge_resources_search_idx ON public.knowledge_resources USING gin (to_tsvector('simple', title || ' ' || summary || ' ' || publisher));
CREATE TABLE public.resource_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), resource_id uuid NOT NULL REFERENCES public.knowledge_resources(id) ON DELETE CASCADE, title text NOT NULL, url text NOT NULL, publisher text NOT NULL, licence_name text NOT NULL DEFAULT 'Unknown — check publisher', reuse_conditions text NOT NULL DEFAULT 'Check the original publisher.', retrieved_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.resource_sources TO anon, authenticated;
GRANT ALL ON public.resource_sources TO service_role;
ALTER TABLE public.resource_sources ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Sources of published resources" ON public.resource_sources FOR SELECT TO anon, authenticated USING (EXISTS (SELECT 1 FROM public.knowledge_resources r WHERE r.id = resource_id AND r.published AND r.rights_status NOT IN ('PENDING_REVIEW','TAKEDOWN_REVIEW','REMOVED')));
CREATE INDEX resource_sources_parent_idx ON public.resource_sources(resource_id);
CREATE TABLE public.resource_downloads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), resource_id uuid NOT NULL REFERENCES public.knowledge_resources(id), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, subscription_id uuid NOT NULL REFERENCES public.subscriptions(id), period_start timestamptz NOT NULL, period_end timestamptz NOT NULL, file_version text NOT NULL, downloaded_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id, resource_id, file_version, subscription_id, period_start));
GRANT SELECT ON public.resource_downloads TO authenticated;
GRANT ALL ON public.resource_downloads TO service_role;
ALTER TABLE public.resource_downloads ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own download history" ON public.resource_downloads FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE INDEX resource_downloads_quota_idx ON public.resource_downloads(user_id, subscription_id, period_start);
CREATE TABLE public.resource_issues (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), resource_id uuid NOT NULL REFERENCES public.knowledge_resources(id), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, issue_type text NOT NULL CHECK (issue_type IN ('EVIDENCE_OUTDATED','SOURCE_BROKEN','COPYRIGHT_CONCERN','INACCURATE_CONTENT','OTHER')), message text NOT NULL CHECK (length(message) BETWEEN 10 AND 2000), status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT, SELECT ON public.resource_issues TO authenticated;
GRANT ALL ON public.resource_issues TO service_role;
ALTER TABLE public.resource_issues ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Submit own resource issue" ON public.resource_issues FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
CREATE POLICY "Read own resource issue" ON public.resource_issues FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.claim_library_download(resource_uuid uuid) RETURNS TABLE(content text, remaining integer, resets_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE uid uuid := auth.uid(); sub public.subscriptions%ROWTYPE; item public.knowledge_resources%ROWTYPE; used_count integer; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Sign in to download.'; END IF; SELECT * INTO item FROM public.knowledge_resources WHERE id = resource_uuid AND kind = 'library' AND published AND access_level = 'analyst' FOR SHARE; IF NOT FOUND OR item.rights_status NOT IN ('OWNED_BY_VERFIAI','PUBLIC_DOMAIN','OPEN_LICENSED','PARTNER_LICENSED') OR NOT item.hosting_allowed OR NOT item.redistribution_allowed OR item.full_content IS NULL OR (item.rights_status IN ('OPEN_LICENSED','PARTNER_LICENSED') AND (NOT item.commercial_reuse_allowed OR item.permission_reference IS NULL OR item.rights_reviewed_at IS NULL)) THEN RAISE EXCEPTION 'This resource is not available for download.'; END IF; SELECT * INTO sub FROM public.subscriptions WHERE user_id = uid AND product_id = 'analyst_plan' AND status IN ('active','trialing') AND current_period_start <= now() AND current_period_end > now() ORDER BY created_at DESC LIMIT 1; IF NOT FOUND THEN RAISE EXCEPTION 'An active Analyst plan is required.'; END IF; PERFORM pg_advisory_xact_lock(hashtext(uid::text || ':' || sub.id::text)); SELECT count(*) INTO used_count FROM public.resource_downloads WHERE user_id = uid AND subscription_id = sub.id AND period_start = sub.current_period_start; IF NOT EXISTS (SELECT 1 FROM public.resource_downloads WHERE user_id = uid AND resource_id = resource_uuid AND file_version = item.file_version AND subscription_id = sub.id AND period_start = sub.current_period_start) THEN IF used_count >= 50 THEN RAISE EXCEPTION 'Your 50 Evidence Library downloads are used for this billing cycle.'; END IF; INSERT INTO public.resource_downloads(resource_id,user_id,subscription_id,period_start,period_end,file_version) VALUES (resource_uuid,uid,sub.id,sub.current_period_start,sub.current_period_end,item.file_version); used_count := used_count + 1; END IF; RETURN QUERY SELECT item.full_content, 50 - used_count, sub.current_period_end; END $$;
REVOKE ALL ON FUNCTION public.claim_library_download(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.claim_library_download(uuid) TO authenticated;